const body = $input.first().json.body || $input.first().json;
const query = (body.query || body.message || body.text || '').trim();
const category = body.category || null;
const history = Array.isArray(body.history) ? body.history.slice(-6) : [];

if (!query) {
  return [{ json: { queryType: 'outofscope', query: '', category, history, reason: 'empty' } }];
}

const q = query.toLowerCase();

// Out of scope check
const oos = [
  /\bweather\b|\btemperature\b|\bforecast\b/,
  /\bstock\b|\bshare price\b|\bnifty\b|\bsensex\b|\bcrypto\b|\bbitcoin\b/,
  /\bcricket\b|\bfootball\b|\bipl\b|\bmovie\b|\bfilm\b|\bsong\b/,
  /^(hi|hello|hey|good morning|good afternoon|good evening|how are you|what is your name|who are you)/,
  /\bjoke\b|\bfunny\b/,
  /capital of |population of |who is the president|who is the prime minister/
];
if (oos.some(p => p.test(q))) {
  return [{ json: { queryType: 'outofscope', query, category, history } }];
}

// Synonym expansion
const synonyms = {
  'ckyc':  'CKYC Central KYC Registry centralised Know Your Customer',
  'kyc':   'KYC Know Your Customer norms requirements compliance',
  'nbfc':  'NBFC Non-Banking Financial Company guidelines directions',
  'ucb':   'UCB Urban Co-operative Bank cooperative',
  'rrb':   'RRB Regional Rural Bank',
  'fema':  'FEMA Foreign Exchange Management Act regulations',
  'npa':   'NPA Non-Performing Asset Non Performing Assets bad loan classification provisioning asset classification income recognition',
  'lcr':   'LCR Liquidity Coverage Ratio guidelines liquidity risk management',
  'crr':   'CRR Cash Reserve Ratio monetary policy master direction',
  'slr':   'SLR Statutory Liquidity Ratio investment requirements',
  'upi':   'UPI Unified Payments Interface payment system digital transaction limit',
  'rtgs':  'RTGS Real Time Gross Settlement large value payment',
  'neft':  'NEFT National Electronic Funds Transfer',
  'nach':  'NACH National Automated Clearing House mandate',
  'imps':  'IMPS Immediate Payment Service instant',
  'ecb':   'ECB External Commercial Borrowing foreign currency loan',
  'fpi':   'FPI Foreign Portfolio Investment securities',
  'nri':   'NRI Non-Resident Indian deposits accounts',
  'fcnr':  'FCNR Foreign Currency Non-Resident deposits',
  'aml':   'AML Anti-Money Laundering prevention detection',
  'pmla':  'PMLA Prevention of Money Laundering Act',
  'msme':  'MSME Micro Small Medium Enterprises lending priority sector',
  'psl':   'PSL Priority Sector Lending targets',
  'lrs':   'LRS Liberalised Remittance Scheme foreign exchange',
  'sarfaesi': 'SARFAESI securitisation asset reconstruction enforcement',
  'digital lending': 'digital lending fintech NBFC LSP Lending Service Provider guidelines directions',
  'pre-payment': 'pre-payment prepayment charges loans MSE MSME directions',
  'gold loan': 'gold loan LTV loan to value ratio directions',
};

const extras = [];
Object.entries(synonyms).forEach(([abbr, expansion]) => {
  if (new RegExp('\\b' + abbr.replace(/[-]/g, '\\-') + '(s)?\\b', 'i').test(q)) extras.push(expansion);
});
const expandedQuery = extras.length > 0 ? query + ' ' + extras.join(' ') : query;

// Date range helper
function dateRange(q) {
  const now = new Date();
  const yr = now.getUTCFullYear();
  const mo = now.getUTCMonth();
  if (/last month|previous month/.test(q)) {
    const s = new Date(Date.UTC(yr, mo-1, 1));
    const e = new Date(Date.UTC(yr, mo, 1));
    return { from: s.toISOString().split('T')[0], to: e.toISOString().split('T')[0], label: 'last month' };
  }
  if (/this month|current month/.test(q)) {
    const s = new Date(Date.UTC(yr, mo, 1));
    return { from: s.toISOString().split('T')[0], to: null, label: 'this month' };
  }
  if (/last week/.test(q)) {
    const s = new Date(Date.UTC(yr, mo, now.getUTCDate()-14));
    const e = new Date(Date.UTC(yr, mo, now.getUTCDate()-7));
    return { from: s.toISOString().split('T')[0], to: e.toISOString().split('T')[0], label: 'last week' };
  }
  if (/this week/.test(q)) {
    const s = new Date(Date.UTC(yr, mo, now.getUTCDate()-7));
    return { from: s.toISOString().split('T')[0], to: null, label: 'this week' };
  }
  if (/this year|current year/.test(q)) {
    return { from: `${yr}-01-01`, to: null, label: 'this year' };
  }
  if (/last year/.test(q)) {
    return { from: `${yr-1}-01-01`, to: `${yr}-01-01`, label: 'last year' };
  }
  return null;
}

if (/how many|total (number|count)|count of circulars|number of circulars/.test(q)) {
  return [{ json: { queryType: 'meta', query, expandedQuery, category, history, dateRange: dateRange(q) } }];
}

// STRICT RECENCY ROUTING: Only trigger if the query is strictly timeline-based (e.g. "what is the latest circular")
// If it specifies technical terms or domain concepts, it must use the RAG path.
const isPureTimelineQuery = /^(what is the latest circular|show latest circulars|any new circulars today|latest circulars|recent circulars)$/.test(q) || 
                            (/^\b(this month|last month|this week|last week)\b$/.test(q) && !/\b(norm|rule|cap|limit|percent|requirement|framework|guideline|direction|kyc|npa|nbfc|lcr|crr|slr|upi|lending|charge)\b/.test(q));

if (isPureTimelineQuery) {
  return [{ json: { queryType: 'recency', query, expandedQuery, category, history, dateRange: dateRange(q) } }];
}

// Force all substantive compliance queries to RAG
return [{ json: { queryType: 'rag', query, expandedQuery, category, history } }];

return [{ json: {
  answer: "I'm the RBI Circular Intelligence assistant — I only help with questions about RBI circulars, regulations, and directions. Try asking about KYC norms, payment system guidelines, FEMA regulations, or specific banking directions.",
  sources: [], replyText: "I'm the RBI Circular Intelligence assistant. I can only help with questions about RBI circulars and regulations.", queryType: 'outofscope'
} }];

const raw = $input.first().json;
const stats = Array.isArray(raw) ? raw[0] : raw;
const meta = $('Is Meta?').first().json;
const catLabel = meta.category ? ` in ${meta.category}` : '';
const dr = meta.dateRange;
const dateLabel = dr ? ` released ${dr.label}` : '';

let answer = `There are **${stats.total || 0}** circulars${catLabel}${dateLabel} in the database.`;
if ((stats.total || 0) > 0) {
  if (dr) {
    answer += `\n\nCovering: ${dr.from} to ${dr.to || 'present'}.`;
  } else {
    answer += `\n\nDatabase spans ${stats.oldest_date} to ${stats.latest_date}.`;
  }
  if (stats.latest_title) {
    answer += `\n\nMost recent circular: "${stats.latest_title}" (${stats.latest_date}).`;
  }
} else {
  answer = `No circulars found${catLabel}${dateLabel} in the database.`;
}

return [{ json: {
  answer,
  sources: stats.latest_url ? [{ title: stats.latest_title, url: stats.latest_url }] : [],
  replyText: answer,
  queryType: 'meta'
} }];

const data = $input.first().json;
const rawQuery = ($('Webhook').first().json.body?.query || $('Webhook').first().json.body?.message || $('Webhook').first().json.body?.text || '').trim();
const embedding = data.data ? data.data[0].embedding : data.embedding;
return [{ json: { query: rawQuery, embedding } }];

