={{
  (() => {
    const classifyNode = $('Classify Query').first().json;
    const payload = {
      query_embedding: $json.embedding,
      query_text: classifyNode.expandedQuery || $json.query,
      match_threshold: 0.25,
      match_count: 6
    };

    // Only inject the key if a strict category filter was actually passed in the webhook
    if (classifyNode.category) {
      payload.filter_category = classifyNode.category;
    }

    return JSON.stringify(payload);
  })()
}}

